var i=`0524-ash-reshteh`;var t=`world-0524`;var s=`IR`;var a=`western-asia`;var r=4;var o=80;var g={en:`Ash Reshteh`,ua:`Аш реште`};var l={en:`A traditional dish from Iran, centered on green lentils, canned chickpeas, yellow onion, spinach. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: зелена сочевиця, консервований нут, жовта цибуля, шпинат. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 40 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 40 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:40,i:[[`green-lentils`,200,`g`],[`canned-chickpeas`,260,`g`],[`water`,1250,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 15 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 15 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:15,i:[[`yellow-onion`,230,`g`],[`spinach`,300,`g`],[`parsley`,90,`g`],[`cilantro`,75,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`wheat-noodles`,210,`g`],[`ground-turmeric`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`plain-yogurt`,170,`g`],[`mint`,13,`g`]]}];var h={slug:i,id:t,country:`IR`,region:a,servings:4,minutes:80,title:g,text:l,steps:d};export{s as country,h as default,t as id,o as minutes,a as region,r as servings,i as slug,d as steps,l as text,g as title};